class KthLargest {
  private all: number[];

  constructor(private k: number, nums: number[]) {
    this.all = nums.slice();
  }

  add(val: number): number {
    this.all.push(val);
    this.all.sort((a, b) => b - a);
    return this.all[this.k - 1];
  }
}

